  "srHowTitle": "كيف تتعرف عليها",
  "srHowBody": "الدعم هو مستوى يتوقف عنده السعر عن الهبوط ويرتد: الطلب يفوق العرض.\nالمقاومة هي مستوى يتوقف عنده السعر عن الصعود وينعكس: العرض يفوق الطلب.\nكلما تجمّع عند المستوى المزيد من الارتدادات أو الرفض، زادت موثوقيته.\nإذا كسر السعر المستوى بقوة وحجم تداول، يتبادل الدعم والمقاومة الأدوار.",
  "srUseTitle": "الاستخدام العملي",
  "srUseBody": "ابحث عن الشراء قرب الدعم، مع وضع وقف الخسارة أسفله مباشرة.\nجنِّ الأرباح أو بِع قرب المقاومة.\nتداول الاختراق فقط بعد تأكيده، ويُفضّل عند إعادة اختبار المستوى.",
