  "mstCustom": "سيناريو مخصص",
  "mstNote": "نموذج مبسّط: الوسيط الحقيقي يقاصّ حسب المنتج ويطبّق هامش صيانة مختلفاً لكل أصل (كريبتو ~0.5%، عقود الفروقات على المؤشرات/الفوركس أعلى). استخدمه لإدراك رتبة حجم المخاطرة، لا كرقم دقيق لوسيطك. الدرس: كلما زادت الرافعة، اقتربت التصفية من حركة سوق عادية.",
