  "ddrTitle": "التراجع (الدروداون) والتعافي",
  "ddrIntro": "رياضيات التراجع غير متماثلة وقاسية: خسارة 50% تتطلب ربح 100% فقط للعودة إلى نقطة البداية. تُظهر هذه الحاسبة كم تحتاج لتستعيد رأس مالك وكم صفقة سيستغرق ذلك بقيمتك المتوقعة الحالية — وهذا سبب قيام الصناديق المحترفة بتقليص الحجم فور تجاوز التراجع حدها (عادة 10-20%).",
  "ddrDrawdown": "التراجع الحالي",
  "ddrExpectancy": "القيمة المتوقعة لكل صفقة",
  "ddrRequired": "الربح المطلوب للتعافي",
  "ddrRequiredSub": "من رأس المال المتبقي، فقط للعودة إلى نقطة التعادل",
  "ddrTrades": "عدد الصفقات المقدَّر",
  "ddrTradesSub": "بمخاطرتك وقيمتك المتوقعة الحاليتين، بفائدة مركبة (∞ = بلا أفضلية لن تتعافى أبداً)",
  "ddrTableTitle": "جدول: الخسارة ← الربح المطلوب",
  "ddrColDd": "التراجع",
  "ddrColReq": "التعافي المطلوب",
  "ddrNote": "السياسة المؤسسية: تحدد الصناديق حداً أقصى مقبولاً للتراجع (مثلاً 15-20%) وقواعد آلية — عند -10% يُخفَّض الحجم إلى النصف، وعند -15% يتوقف التداول ويُراجَع النظام. كما يحدّ الـVaR اليومي (القيمة المعرضة للخطر) مما يمكن أن يخسره المكتب في يوم عادي. انسخ الفكرة: حدد حدَّك أنت قبل التداول، لا أثناء الهبوط.",
  "heatCorrLabel": "متوسط الارتباط بين المراكز",
  "heatEffective": "الخطر الفعلي المعدَّل بالارتباط",
  "heatEffectiveSub": "بين التنويع الكامل (0%) وصفقة واحدة كبيرة (100%). عدة أزواج دولار أو عدة أسهم تقنية ≈ 60-90%.",
  "gkTitle": "إغريقيات الخيارات",
  "gkIntro": "تقيس الإغريقيات كيف يتغير سعر الخيار عندما يتحرك كل متغير: الأصل الأساسي، الزمن، التقلب، وأسعار الفائدة. إنها لوحة عدادات متداول الخيارات — بدونها تطير أعمى. كل بطاقة تتضمن مثالاً رقمياً؛ ثم تدرَّب على حاسبة بلاك-شولز في قسم الخيارات.",
  "mlqTitle": "الهامش والتصفية في المشتقات",
  "mlqIntro": "إذا كنت تتداول العقود الآجلة أو الدائمة برافعة مالية، فالهامش هو شريان حياتك. معظم الحسابات لا تموت بسبب تحليل سيئ، بل بسبب عدم فهم كيف ومتى تقوم المنصة بتصفيتك. يشرح هذا الوحدة أوضاع الهامش وأوضاع المركز وسعر التصفية وكيفية حماية نفسك من فتائل التلاعب.",
  "ntTitle": "تداول الأخبار والأحداث",
  "ntIntro": "البيانات عالية التأثير (الوظائف، التضخم، الفائدة) تحرّك السوق في ثوانٍ. معرفة ما تفعله قبلها وأثناءها وبعدها تفصل الفرصة عن الحساب المحروق. استخدم التقويم الاقتصادي في لوحة التحكم.",
  "smTitle": "معنويات السوق",
  "smIntro": "تقيس ما تشعر به الجموع: خوف أم جشع. عند التطرف تصبح المعنويات وقودًا عكسيًا — حين يكون الجميع صاعدين لا يبقى من يشتري. تكمّل تقرير COT في هذا الركن.",
  "imTitle": "التحليل بين الأسواق",
  "imIntro": "لا سوق يتحرك وحده (جون ميرفي). الدولار والسندات والسلع والأسهم مترابطة: قراءة تلك العلاقات تمنحك السياق الكلي الذي يؤكد صفقتك — أو يدحضها. إنها 15% من امتحان CMT لسبب.",
