  "aiCoachIntro_91e0e7": "اضغط {analyzeBold} وسيراجع Claude Sonnet 4.5 استراتيجيتك الحالية: نقاط القوة، المخاطر، التحسينات القابلة للتنفيذ والحكم النهائي. مصمم كمدرب أول لتداول التقلبات.",
