  "thetaNegative_91e0f0": "ثيتا سالبة: تدفع علاوة تتآكل كل يوم. تحتاج أن تحدث الحركة قريباً قبل أن يؤدي الوقت إلى تآكل القيمة.",
  "thetaPositive_91e0f1": "ثيتا موجبة: تحصّل علاوة. الوقت في صالحك — إذا لم يتحرك السعر، تكسب من التآكل اليومي.",
  "thetaNeutral_91e0f2": "ثيتا محايدة: المراكز الطويلة والقصيرة تتعادل. حركة السعر أهم من الوقت.",
  "unlimitedRiskUp_91e0f3": "مخاطر غير محدودة صعوداً. يتطلب هامش عالٍ ووقف خسارة منضبط.",
