  "assignPut_91e0f6": "إذا انخفض {symbol} تحت ${strike} وأبقيت المركز، سيتم تخصيص 100 سهم/عقد لك بسعر التنفيذ.",
  "assignCall_91e0f7": "إذا ارتفع {symbol} فوق ${strike} وأبقيت المركز، ستسلم 100 سهم/عقد (إذا كان كول مغطى قصير) أو ستغطي بخسارة (إذا كان مكشوف).",
