  "gd_decaimientoDiarioLosVende_98a6f4d5": "الانحلال اليومي. البائعون يحصلون على Theta؛ المشترون يدفعونه.",
  "gd_vega_f1e18b4a": "Vega ν",
  "gd_siIvSube1_c5b35b3e": "إذا ارتفع IV بنسبة 1%، فإن مركزك يربح/يخسر Vega دولار. شراء الخيارات = long Vega.",
  "gd_probBeneficioPop_819a0c8f": "احتمالية الربح (PoP)",
