  "basicsHeroTitle": "المفاهيم الأساسية في التداول",
  "basicsHeroDesc": "قبل فتح أول صفقة، تحتاج إلى إتقان خمسة مفاهيم: Long وShort وTake Profit (TP) وStop Loss (SL) وحجم المركز. هذه هي اللبنات الأساسية التي يُبنى عليها أي استراتيجية تداول، بغض النظر عن الأصل أو الإطار الزمني.",
