  "basicsImportant": "مهم:",
  "basicsLongTitle": "Long (مركز طويل / شراء)",
  "basicsLongBadge": "صعودي",
  "basicsLongDesc": "المركز الطويل (Long) هو رهان على ارتفاع السعر. تشتري الأصل بسعر معين وتبيعه عندما يرتفع السعر، محققاً الفرق كربح. إنها العملية الأكثر طبيعية: \"اشتر بسعر منخفض وبع بسعر مرتفع\".",
  "basicsLongWhenDesc": "إشارة صعودية، اختراق مستوى مقاومة، دعم قوي",
  "basicsLongWinDesc": "يرتفع السعر فوق سعر دخولك",
  "basicsLongLoseDesc": "ينخفض السعر دون سعر دخولك",
  "basicsLongDiagramCaption": "تشتري → يرتفع السعر → تربح",
  "basicsLongFormulaTitle": "معادلة الربح (Long)",
  "basicsLongFormula": "PnL = (سعر الخروج − سعر الدخول) × الكمية",
  "basicsLongFormulaExample": "مثال: تشتري 1 BTC بـ $90,000 وتبيعه بـ $95,000 → PnL = +$5,000",
  "basicsFaqLongTitle": "الأسئلة الشائعة — Long",
  "basicsFaqLong1Q": "ماذا يعني أن تكون في مركز Long؟",
  "basicsFaqLong1A": "أن تكون في مركز Long يعني أنك اشتريت أصلاً تتوقع ارتفاع سعره. تربح عندما يرتفع السعر فوق سعر دخولك. إنها العملية الأكثر سهولة: \"اشتر بسعر منخفض وبع بسعر مرتفع\".",
  "basicsFaqLong2Q": "متى تفتح مركز Long؟",
  "basicsFaqLong2A": "عندما يشير التحليل إلى احتمال ارتفاع السعر: بعد اختراق مستوى المقاومة، أو عند دعم قوي، أو مع تأكيد momentum صعودي، أو بعد ظهور إشارة نمط صعودي على الرسم البياني.",
  "basicsFaqLong3Q": "هل يمكنني أن أخسر أكثر مما استثمرته في Long بدون leverage؟",
  "basicsFaqLong3A": "لا. بدون leverage، الخسارة القصوى هي 100% من المبلغ المستثمر (إذا وصل سعر الأصل إلى الصفر). مع leverage يمكن تصفية حسابك مبكراً، ولهذا يُعدّ SL أمراً بالغ الأهمية.",
  "basicsShortTitle": "Short (مركز قصير / بيع)",
  "basicsShortBadge": "هبوطي",
  "basicsShortDesc": "المركز القصير (Short) هو رهان على انخفاض السعر. \"تقترض\" الأصل من الوسيط وتبيعه بالسعر الحالي، ثم تعيد شراءه بسعر أقل عندما ينخفض. الفرق بين سعر البيع وسعر إعادة الشراء هو ربحك.",
  "basicsShortWarning": "في Short الخسائر نظرياً غير محدودة (يمكن للسعر أن يرتفع بلا سقف). استخدم دائماً Stop Loss.",
  "basicsShortWhenDesc": "اتجاه هبوطي، اختراق مستوى دعم، نمط هبوطي",
  "basicsShortWinDesc": "ينخفض السعر دون سعر دخولك (البيع)",
  "basicsShortLoseDesc": "يرتفع السعر فوق سعر دخولك",
  "basicsShortDiagramCaption": "تبيع → ينخفض السعر → تربح",
  "basicsShortFormulaTitle": "معادلة الربح (Short)",
  "basicsShortFormula": "PnL = (سعر الدخول − سعر الخروج) × الكمية",
  "basicsShortFormulaExample": "مثال: تبيع 1 BTC بـ $90,000 وتعيد شراءه بـ $85,000 → PnL = +$5,000",
  "basicsCompareTitle": "Long مقابل Short — مقارنة سريعة",
