  "basicsMicroTitle": "Micro Lot (0.01)",
  "basicsMicroUnits": "1,000 units",
  "basicsMicroDesc": "الوحدة الدنيا المتاحة في معظم الوسطاء. مثالية للتعلم دون تدمير الحساب. مع 10 pip عكسك تخسر $1 فقط. مثالية لاختبار الاستراتيجيات في السوق الحقيقية بمخاطرة دنيا.",
  "basicsMicroTip": "استخدمه للتحقق من الاستراتيجيات في السوق الحقيقية بمخاطرة مُتحكَّم بها.",
  "basicsMiniTitle": "Mini Lot (0.1)",
  "basicsMiniUnits": "10,000 units",
  "basicsMiniDesc": "10 أضعاف micro lot. الحجم القياسي للحسابات في مرحلة النمو. يتيح التنويع في عدة مراكز متزامنة دون التعرض المفرط.",
  "basicsMiniTip": "نقطة الانطلاق المثالية للمتداولين المتوسطين بحسابات $1,000–$10,000.",
  "basicsStdTitle": "Lot القياسي (1.0)",
  "basicsStdUnits": "100,000 units",
  "basicsStdDesc": "وحدة المرجع في سوق الفوركس. كل pip يُحرّك $10 في EUR/USD. مع SL بـ 50 pip تُخاطر بـ $500 — تحتاج على الأقل $25,000–$50,000 للمخاطرة بـ 1-2% فقط لكل صفقة.",
  "basicsStdWarning": "لا تستخدم Lot قياسياً مع حسابات صغيرة: ستكون المخاطرة لكل صفقة مفرطة.",
  "basicsMacroTitle": "Macro / كبير (10+ lots)",
  "basicsMacroUnits": "1M+ units",
  "basicsMacroDesc": "منطقة المؤسسات. تتداول البنوك والصناديق وصناديق التحوط بهذا الحجم. مع 100 lot، كل pip يساوي $1,000. هذه المراكز كثيراً ما تُحرّك السعر وتُنشئ مستويات الدعم/المقاومة التي نراها على الرسم البياني.",
  "basicsMacroInfo": "معرفة هذه الأحجام تساعدك على فهم سبب احترام السعر لمستويات معينة.",
  "basicsPosFormulaTitle": "كيف تحسب حجم مركزك الأمثل",
  "basicsPosFormulaLabel": "المعادلة الشاملة",
  "basicsPosFormula": "Lots = (رأس المال × %المخاطرة) ÷ (Pips_SL × Pip_Value)",
  "basicsPosFormulaExLabel": "Practical example:",
  "basicsPosFormulaExDesc": "Capital: $5,000 | Risk: 1% | SL: 50 pips",
  "basicsPosFormulaExResult": "Lots = ($5,000 × 0.01) ÷ (50 × $1) = 1.0 mini lot",
  "basicsPosGuideTitle": "Quick guide by capital",
  "basicsPosGuideNote": "* Assuming SL of 100 pips in EUR/USD",
  "basicsPosWarningTitle": "الخطأ الأكثر شيوعاً: المبالغة في حجم المركز",
  "basicsPosWarning": "فتح 1 lot قياسي لأن \"الحركة تبدو مضمونة\" بينما حسابك $2,000 يعني أن SL بـ 20 pip (−$200) يجعلك تخسر 10% من رأس مالك في صفقة واحدة. احسب دائماً الـ lot من المخاطرة القصوى المسموح بها (1-2%)، وليس العكس.",
  "basicsFaqPosTitle": "الأسئلة الشائعة — حجم المركز",
  "basicsFaqPos1Q": "ما هو Lot في التداول؟",
  "basicsFaqPos1A": "Lot هو وحدة القياس القياسية لحجم المركز في الفوركس والعقود مقابل الفروق (CFDs). 1 lot قياسي يعادل 100,000 وحدة من العملة الأساسية. هذا التوحيد يتيح حساب قيمة pip ومخاطرة كل صفقة بسهولة.",
  "basicsFaqPos2Q": "بأي حجم Lot يجب أن أبدأ؟",
  "basicsFaqPos2A": "إذا كان حسابك أقل من $1,000، ابدأ بـ micro lot (0.01). إذا كان بين $1,000 و$10,000، استخدم mini lot (0.1). الـ lot القياسية تتطلب حسابات $10,000+ لإدارة مخاطر سليمة (المخاطرة بـ 1-2% فقط لكل صفقة).",
  "basicsFaqPos3Q": "كيف يؤثر leverage على حجم المركز؟",
  "basicsFaqPos3A": "يتيح لك leverage التحكم في lot قياسي (100,000 وحدة) برأس مال أقل بكثير. مع 1:100 تحتاج فقط $1,000 هامشاً لـ 1 lot. لكن leverage يُضخّم الأرباح والخسائر بالتساوي: 1 lot مع leverage 1:100 في EUR/USD تعني $10/pip ربحاً أو خسارة.",
  "basicsFaqPos4Q": "ما هي قيمة pip وكيف تُحسب؟",
  "basicsFaqPos4A": "Pip هو أصغر حركة للسعر (0.0001 في EUR/USD). قيمة pip = (0.0001 × lot × 100,000) بالعملة المُقيَّمة. في EUR/USD: 1 lot قياسي → $10/pip | 1 mini lot → $1/pip | 1 micro lot → $0.10/pip.",
  "basicsFaqPos5Q": "لماذا تستخدم المؤسسات lots كبيرة؟",
  "basicsFaqPos5A": "تُحرّك صناديق الاستثمار والبنوك وصناديق التحوط مئات الملايين من الدولارات. مع 100 lot قياسي (10 ملايين وحدة) كل pip يساوي $1,000. على هذا الحجم، تحريك السعر بضعة pip يعني عشرات الآلاف في PnL. لهذا تظهر مداخلهم ومخارجهم كثيراً كمستويات دعم/مقاومة على الرسم البياني.",
  "basicsSummaryTitle": "الخلاصة: المفاهيم الخمسة معاً",
