  "strat_csp_desc": "بيع خيار بيع مع تجنيب 100% من سعر التنفيذ نقداً. العائد نفسه كبيع الخيار، لكن رأس المال المحجوز مختلف.",
  "strat_protective_put_desc": "أسهم مع خيار بيع مُشترى أدناها: تأمين بخصم تحمّل.",
  "strat_covered_put_desc": "بيع السهم على المكشوف مع بيع خيار بيع. يحصّل العلاوة ما لم يرتفع السعر.",
  "strat_covered_strangle_desc": "أسهم مع بيع خيار شراء وخيار بيع خارج النقد. علاوة مزدوجة والتزام من الجانبين.",
  "strat_ratio_call_write_desc": "أسهم مع بيع خيارَي شراء: أحدهما مغطى والآخر مكشوف.",
  "strat_ratio_put_write_desc": "بيع السهم على المكشوف مع بيع خيارَي بيع: أحدهما مغطى والآخر مكشوف.",
  "strat_stock_repair_desc": "على مركز خاسر: شراء خيار شراء وبيع اثنين أعلى منه لخفض نقطة التعادل دون أموال إضافية.",
  "strat_call_calendar_desc": "بيع خيار الشراء القريب وشراء نفس الخيار لأجل أبعد. يعتمد على تسارع تآكل الوقت في الرجل المُباعة.",
  "strat_put_calendar_desc": "بيع خيار البيع القريب وشراء نفس الخيار لأجل أبعد.",
  "strat_call_diagonal_desc": "كالندر بأسعار تنفيذ مختلفة: الرجل المُباعة الأعلى تضيف ميلاً صعودياً.",
  "strat_put_diagonal_desc": "كالندر خيارات بيع بأسعار تنفيذ مختلفة: الرجل المُباعة الأدنى تضيف ميلاً هبوطياً.",
  "strat_double_calendar_desc": "كالندران: أحدهما بخيارات بيع أدنى والآخر بخيارات شراء أعلى. يربح إذا انتهى السعر بينهما.",
  "strat_double_diagonal_desc": "كالندر مزدوج بأرجل شراء أبعد: يوسّع منطقة الربح مقابل مدين أكبر.",
  "strat_jelly_roll_desc": "الفرق بين مركبين اصطناعيين بنفس سعر التنفيذ في أجلين. سعره سعر فائدة وتوزيعات بحتة.",
  "strat_pmcc_desc": "خيار شراء عميق داخل النقد وطويل الأجل يحلّ محل السهم، ويُباع مقابله خيار قريب. كوفرد كول دون شراء 100 سهم.",
  "strat_zebra_desc": "شراء خيارَي شراء داخل النقد مقابل بيع واحد: دلتا قرابة 100 دون قيمة زمنية صافية.",
  "strat_risk_reversal_desc": "يموّل شراء خيار الشراء ببيع خيار بيع. مركب صعودي بتكلفة تقارب الصفر.",
  "strat_seagull_desc": "انعكاس مخاطرة مع سقف عبر بيع خيار شراء أعلى: هيكل أرخص مقابل التنازل عن الجزء الأخير.",
  "strat_big_lizard_desc": "سترادل مُباع مع شراء خيار شراء أعلى: يلغي مخاطر الصعود ويُبقي مخاطر الهبوط فقط.",
  "strat_reverse_jade_desc": "خيار شراء مُباع مع فارق خيارات بيع مُباع: بلا مخاطر هبوطية، ومع مخاطر صعودية.",
  "strat_long_call_condor_desc": "أربعة خيارات شراء تحدّد هضبة ربح بين سعرَي التنفيذ الداخليين.",
  "strat_long_put_condor_desc": "نفس الكوندور مبنياً بالكامل من خيارات البيع.",
  "strat_long_put_butterfly_desc": "فراشة خيارات بيع: الحد الأقصى عند سعر التنفيذ الأوسط والمخاطرة محدودة بالمدين.",
  "strat_put_bwb_desc": "فراشة خيارات بيع بجناح أعرض من الآخر. تُفتح عادة بائتمان وتنقل المخاطرة كلها إلى جانب واحد.",
  "strat_xmas_call_desc": "فراشة خيارات شراء غير متماثلة بنسبة 1-3-2: أرخص من الكلاسيكية مع إزاحة منطقة الربح.",
  "strat_xmas_put_desc": "نسخة خيارات البيع من فراشة 1-3-2، مُزاحة إلى الأسفل.",
  "strat_bull_call_ladder_desc": "فارق شراء صعودي مع بيع خيار شراء ثالث أعلى. الائتمان الإضافي يفتح مخاطرة غير محدودة صعوداً.",
  "strat_bear_call_ladder_desc": "بيع خيار شراء أدنى وشراء اثنين أعلى: يخسر داخل النطاق ويربح مع صعود كبير.",
  "strat_bull_put_ladder_desc": "بيع خيار بيع أعلى وشراء اثنين أدنى: يخسر داخل النطاق ويربح مع هبوط حاد.",
  "strat_bear_put_ladder_desc": "فارق بيع هبوطي مع بيع خيار بيع ثالث أدنى. الائتمان الإضافي يفتح مخاطرة هبوطاً.",
  "strat_box_desc": "فارق شراء صعودي مع فارق بيع هبوطي على نفس أسعار التنفيذ. قيمته فرق التنفيذ مخصوماً: قرض اصطناعي.",
  "strat_conversion_desc": "أسهم مع شراء خيار بيع وبيع خيار شراء عند نفس سعر التنفيذ: مركز بلا مخاطرة اتجاهية قيمته تكلفة الاحتفاظ.",
  "strat_reversal_desc": "عكس التحويل: بيع السهم على المكشوف مع شراء خيار شراء وبيع خيار بيع.",
